INSERT INTO pages (id, title, slug, body_markdown, published, created_at, updated_at, layout, public_id) VALUES (1, 'About Fernwood', 'about', 'Fernwood Supply Co. is a small shop on SE Belmont in Portland, Oregon. We opened in a former bike repair garage in 2019 with a coffee bar, a few shelves of mugs, and a strong opinion that everyday objects should be made well.
INSERT INTO pages (id, title, slug, body_markdown, published, created_at, updated_at, layout, public_id) VALUES (2, 'Shipping & Delivery', 'shipping', 'We pack and ship orders **Monday through Friday** from the shop in Portland. Most orders leave within 1–2 business days.
